// Copy for the chat-report flow in the six site languages.
// Each entry: [en, es, fr, de, it, pl]. {name} placeholders are filled by tr().
// Voice: Clara, a warm and honest friend. Informal everywhere (tú / tu / du / tu / ty).
export type Lang = "en" | "es" | "fr" | "de" | "it" | "pl";
const LANGS: Lang[] = ["en", "es", "fr", "de", "it", "pl"];
const LOCALES: Record<Lang, string> = { en: "en-US", es: "es-ES", fr: "fr-FR", de: "de-DE", it: "it-IT", pl: "pl-PL" };

let current: Lang | null = null;
/** Pin the language (SSR prerender passes the route's locale). */
export function setLang(l: string) { if ((LANGS as string[]).includes(l)) current = l as Lang; }
export function lang(): Lang {
  if (current) return current;
  if (typeof document !== "undefined") {
    const l = (document.documentElement.lang || "").slice(0, 2);
    if ((LANGS as string[]).includes(l)) return l as Lang;
  }
  return "en";
}
/** BCP-47 locale for Intl (numbers, dates, month names). */
export const loc = () => LOCALES[lang()];
/** Home of the site in this language. */
export const homePath = () => (lang() === "en" ? "/" : `/${lang()}/`);
/** Clara's name, localized (the pun on "clear" works in each language). */
export const claraName = () => ({ en: "Clara", es: "Clara", fr: "Claire", de: "Klara", it: "Chiara", pl: "Klara" })[lang()];

