/** Translate `id`, filling {placeholders}. Falls back to English, then Spanish. */
export function tr(id: string, vars: Record<string, string | number> = {}): string {
  const row = D[id];
  const i = LANGS.indexOf(lang());
  let s = row ? (row[i] || row[0] || row[1]) : id;
  for (const [k, v] of Object.entries(vars)) s = s.split(`{${k}}`).join(String(v));
  return s.split("{clara}").join(claraName());
}
